97	   */
98	  private parseGrepLine(line: string, basePath: string): GrepMatch | null {
99	    if (!line.trim()) return null;
100	
101	    // Use regex to locate the first occurrence of :<digits>:
102	    // This allows filenames to contain colons, as long as they don't look like :<digits>:
103	    // Note: This regex assumes filenames do not contain colons, or at least not followed by digits.
104	    const match = line.match(/^(.+?):(\d+):(.*)$/);
105	    if (!match) return null;
106	
107	    const [, filePathRaw, lineNumberStr, lineContent] = match;
108	    const lineNumber = parseInt(lineNumberStr, 10);
109	
110	    if (!isNaN(lineNumber)) {
111	      const absoluteFilePath = path.resolve(basePath, filePathRaw);
112	      const relativeCheck = path.relative(basePath, absoluteFilePath);
113	      if (
114	        relativeCheck === '..' ||
115	        relativeCheck.startsWith(`..${path.sep}`) ||
116	        path.isAbsolute(relativeCheck)
117	      ) {
118	        return null;
119	      }
120	
121	      const relativeFilePath = path.relative(basePath, absoluteFilePath);
122	
123	      return {
124	        filePath: relativeFilePath || path.basename(absoluteFilePath),
125	        absolutePath: absoluteFilePath,
126	        lineNumber,
127	        line: lineContent,
128	      };
129	    }
130	    return null;
131	  }
