36	function getRgCandidateFilenames(): readonly string[] {
37	  return process.platform === 'win32' ? ['rg.exe', 'rg'] : ['rg'];
38	}
39	
40	async function resolveExistingRgPath(): Promise<string | null> {
41	  const binDir = Storage.getGlobalBinDir();
42	  for (const fileName of getRgCandidateFilenames()) {
43	    const candidatePath = path.join(binDir, fileName);
44	    if (await fileExists(candidatePath)) {
45	      return candidatePath;
46	    }
47	  }
48	  return null;
49	}
50	
51	let ripgrepAcquisitionPromise: Promise<string | null> | null = null;
52	
53	async function ensureRipgrepAvailable(): Promise<string | null> {
54	  const existingPath = await resolveExistingRgPath();
55	  if (existingPath) {
56	    return existingPath;
57	  }
58	  if (!ripgrepAcquisitionPromise) {
59	    ripgrepAcquisitionPromise = (async () => {
60	      try {
61	        await downloadRipGrep(Storage.getGlobalBinDir());
62	        return await resolveExistingRgPath();
63	      } finally {
64	        ripgrepAcquisitionPromise = null;
65	      }
66	    })();
67	  }
68	  return ripgrepAcquisitionPromise;
69	}
